#include <stddef.h>

int main(void)
{
    const int temperatures[] = {18, 21, 19, 24};
    const size_t count = sizeof temperatures / sizeof temperatures[0];
    size_t selected = 2U;

    if (selected >= count) {
        return 1;
    }
    return temperatures[selected] == 19 ? 0 : 2;
}
